sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    // Retrieve values using exact column names
    var requestType = current.getValue('u_request_type') || current.getValue('request_type');
    var configItem = current.getValue('u_configuration_item') || current.getValue('cmdb_ci');
    var requestedFor = current.getValue('u_requested_for') || current.getValue('requested_for');
    var tierSpecs = current.getValue('u_vdi_tier_specs');

    // 1. Handle Decommission: Retire the existing linked CI
    if (requestType == 'decommission') {
        if (configItem) {
            var grExistingCI = new GlideRecord('cmdb_ci_virtual_desktop');
            if (grExistingCI.get(configItem)) {
                grExistingCI.setValue('install_status', '7'); // Retired
                grExistingCI.setValue('operational_status', '2'); // Non-Operational
                grExistingCI.work_notes = 'Decommissioned automatically via Request: ' + current.getValue('number');
                grExistingCI.update();

                gs.addInfoMessage('Associated Cloud PC asset has been marked as Retired.');
            }
        }
        return;
    }

    // 2. Handle Upgrades: Update specs on the existing linked CI
    if (requestType == 'upgrade') {
        if (configItem) {
            var grUpgradeCI = new GlideRecord('cmdb_ci_virtual_desktop');
            if (grUpgradeCI.get(configItem)) {
                if (tierSpecs == 'high-end') {
                    grUpgradeCI.setValue('u_ram_gb', '32'); 
                    grUpgradeCI.setValue('u_cpu_core', '8');
                } else if (tierSpecs == 'mid-range') {
                    grUpgradeCI.setValue('u_ram_gb', '16'); 
                    grUpgradeCI.setValue('u_cpu_core', '4');
                }
                grUpgradeCI.work_notes = 'Specs upgraded via Request: ' + current.getValue('number');
                grUpgradeCI.update();

                gs.addInfoMessage('Existing Cloud PC specifications have been updated.');
            }
        }
        return;
    }

    // 3. Handle New Provisions: Create a new CI record in cmdb_ci_virtual_desktop
    if (requestType == 'new_standard' || requestType == 'new_high-end') {
        var grNewCI = new GlideRecord('cmdb_ci_virtual_desktop');
        grNewCI.initialize();

        var randomNum = Math.floor(1000 + Math.random() * 9000);
        grNewCI.setValue('name', 'AVD-W11-' + randomNum);
        grNewCI.setValue('u_hostname', 'AVD-W11-' + randomNum);
        grNewCI.setValue('u_operating_system', 'Windows 11');
        grNewCI.setValue('assigned_to', requestedFor);
        grNewCI.setValue('install_status', '1'); // Installed

        if (tierSpecs == 'high-end' || requestType == 'new_high-end') {
            grNewCI.setValue('u_ram_gb', '32');
            grNewCI.setValue('u_cpu_core', '8');
        } else {
            grNewCI.setValue('u_ram_gb', '8');
            grNewCI.setValue('u_cpu_core', '2');
        }

        var newCiSysId = grNewCI.insert();

        // Link the newly created CI back to this Request record
        if (newCiSysId) {
            var grCurrentReq = new GlideRecord(current.getTableName());
            if (grCurrentReq.get(current.getUniqueValue())) {
                var ciFieldName = current.isValidField('u_configuration_item') ? 'u_configuration_item' : 'cmdb_ci';
                grCurrentReq.setValue(ciFieldName, newCiSysId);
                grCurrentReq.setWorkflow(false); // Prevents triggering business rules in an infinite loop
                grCurrentReq.update();
            }
            gs.addInfoMessage('New Cloud PC ' + grNewCI.getValue('u_hostname') + ' registered and linked.');
        }
    }

})(current, previous);
